@Test
@DisplayName("两个锚点迁移后区间交叉：422；端点相接允许通过")
void movedRangesCross() {
    List<AnchorRow> anchors = List.of(
            anchor(1, 0, 5, "hello"), anchor(2, 6, 11, "world"));
    // 新文本 "hello world" 长度 11：两个映射区间重叠
    assertThatThrownBy(() -> service.validateRevision("s1", "en", "hello world", anchors,
            List.of(new AnchorMappingInput(1, 0, 6), new AnchorMappingInput(2, 5, 10))))
            .isInstanceOf(ApiException.class)
            .hasMessageContaining("迁移后锚点区间交叉");

    // 端点相接（[0,5) 与 [5,10)）不交叉，可通过
    List<CitationService.MovedAnchor> moved = service.validateRevision("s1", "en", "helloworld!",
            anchors, List.of(new AnchorMappingInput(1, 0, 5), new AnchorMappingInput(2, 5, 10)));
    assertThat(moved).hasSize(2);
}

